const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seeds=[['넥스트팜','NF','AI 기반 스마트팜으로 농업의 새로운 기준을 만듭니다','농생명·푸드','전주시','김도윤',true,'Series A','18','30'],['카본웨이브','CW','가볍고 강한 탄소복합소재, 모빌리티의 미래를 설계합니다','첨단소재','전주시','이서준',true,'Pre-A','8','15'],['그린바이오랩','GB','자연에서 찾은 소재로 지속가능한 일상을 만듭니다','바이오·헬스','익산시','박지현',true,'Seed','3','10'],['모빌리온','MO','전기차 배터리의 수명을 늘리는 지능형 관리 솔루션','미래모빌리티','군산시','정민수',false,'Series A','25','0'],['온유푸드','ON','지역의 좋은 원료로 만드는 건강한 대체 단백질','농생명·푸드','익산시','최유진',true,'Pre-A','6','12'],['딥비전테크','DV','제조 현장의 불량을 찾아내는 AI 비전 검사 솔루션','AI·SW','전주시','강현우',true,'Seed','4','8'],['에코루프','EL','폐자원을 새로운 자원으로 연결하는 순환경제 플랫폼','에너지·환경','군산시','윤서연',false,'Pre-A','10','0'],['메디센스','MS','일상 속 건강 신호를 읽는 웨어러블 헬스케어','바이오·헬스','정읍시','한지우',true,'Seed','2','7'],['루트로보틱스','RR','사람과 함께 일하는 협동 로봇 자동화 솔루션','로봇·제조','완주군','오준호',true,'Pre-A','7','20'],['블루하버','BH','데이터로 관리하는 친환경 수산 양식','농생명·푸드','부안군','신하린',false,'Seed','3','0'],['솔라브릿지','SB','분산형 태양광 발전을 위한 에너지 관리 기술','에너지·환경','김제시','장민재',true,'Series A','20','40'],['로컬인사이트','LI','지역 상권의 변화를 읽는 데이터 분석 서비스','AI·SW','남원시','조수빈',false,'Seed','1','0']].map((a,i)=>({id:String(i+1),name:a[0],logo:a[1],summary:a[2],sector:a[3],city:a[4],ceo:a[5],stage:a[7],raised:a[8],visible:true,founded:'2021-03-15',team:'대표 및 핵심팀: 관련 산업 연구개발·사업화 경력 10년 이상',description:a[2]+'.\n전북의 산업 기반과 자체 연구개발 역량을 바탕으로 고객이 현장에서 겪는 문제를 해결합니다. 제품 개발부터 실증, 사업화까지 일관된 서비스를 제공합니다.',achievements:'2025 · 주요 고객사 대상 현장 실증 완료\n2024 · 핵심 기술 특허 2건 등록\n2023 · 초기 제품 출시 및 첫 매출 달성',irName:a[0]+'_IR_샘플.txt'}));
let companies=JSON.parse(localStorage.getItem('jb-companies')||'null')||seeds,user=JSON.parse(sessionStorage.getItem('jb-user')||'null'),favorites=JSON.parse(localStorage.getItem('jb-favs')||'{}'),query='',sectorFilter='',stageFilter='',page=1,sort='latest';
companies=companies.map(refreshSampleCompany).map(normalizeCompany);
function persist(){localStorage.setItem('jb-companies',JSON.stringify(companies))}function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.tt);window.tt=setTimeout(()=>$('#toast').style.display='none',3000)}function go(p){location.hash=p}function login(role,email){user={role,email:email||role+'@demo.local'};sessionStorage.setItem('jb-user',JSON.stringify(user));go(role==='admin'?'/admin':'/mypage');toast('로그인되었습니다')}function logout(){user=null;sessionStorage.removeItem('jb-user');go('/');render()}
const roleName={company:'기업 회원',investor:'투자사 회원',admin:'관리자'};function shell(body){$('#app').innerHTML=`<header><a class="brand" href="#/"><span class="mark">JB</span><span>JB-PORT<small>전북 투자정보사이트</small></span></a><nav><a class="${!location.hash.includes("mypage")&&!location.hash.includes("admin")?"active":""}" href="#/">기업정보</a><a class="${location.hash.includes("mypage")||location.hash.includes("admin")?"active":""}" href="${user?.role==='admin'?'#/admin':'#/mypage'}">${user?.role==='admin'?'관리자페이지':'마이페이지'}</a></nav><div class="account">${user?`<a href="#/mypage">${user.role==='admin'?'관리자페이지':roleName[user.role]}</a><button class="btn" onclick="logout()">로그아웃</button>`:'<a href="#/login">로그인</a><a class="btn primary" href="#/signup">회원가입</a>'}</div></header><main>${body}</main><footer><span><b>JB-PORT</b> &nbsp; 전북의 기업과 투자를 연결합니다.</span><span>가상 기업 데이터 · 브라우저 저장형 프로토타입 &nbsp; <a href="#/login">체험 로그인</a></span></footer>`}

function row(c){return `<a class="directory-row" href="#/company/${c.id}" aria-label="${esc(c.name)} 기업 상세보기"><div class="directory-name"><h3>${esc(c.name)}</h3></div><div class="directory-representative">${esc(c.ceo||"-")}</div><div class="directory-item">${esc(c.oneLineDescription||c.summary)}</div><div class="directory-sector">${esc(c.businessSector||c.sector)}</div><div class="directory-location">${esc((c.headOffice||c.city||"").match(/(?:[가-힣]+시|[가-힣]+군)/)?.[0]||c.city||"-")}</div><div class="directory-stage">${esc(c.stage||"-")}</div></a>`}
function filtered(){let list=companies.filter(c=>c.visible&&(!stageFilter||c.stage===stageFilter)&&(!sectorFilter||c.businessSector===sectorFilter)&&[c.name,c.summary,c.businessSector,c.city,c.ceo].some(x=>String(x||'').toLowerCase().includes(query.trim().toLowerCase())));if(sort==='latest')list.sort((a,b)=>companyRegisteredTime(b)-companyRegisteredTime(a));if(sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name,'ko'));return list}
function listContent(){const list=filtered(),n=Math.ceil(list.length/12);page=Math.min(page,n||1);$('#results').innerHTML=`<div class="listbar"><span>총 <b>${list.length}</b>개 기업</span></div><div class="directory-scroll" tabindex="0" role="region" aria-label="기업 목록 · 좌우로 스크롤하여 모든 항목 확인"><div class="directory-grid"><div class="directory-columns"><span>기업명</span><span>대표자명</span><span>사업 아이템</span><span>사업 분야</span><span>본점 소재지</span><span>투자 단계</span></div>${list.length?list.slice((page-1)*12,page*12).map(row).join(''):'<div class="empty">검색 조건에 맞는 기업이 없습니다.<br><br><button class="btn" onclick="query=\'\';sectorFilter=\'\';stageFilter=\'\';render()">전체 기업 보기</button></div>'}</div></div><div class="pagination">${n>1?`<button aria-label="이전 페이지" ${page===1?'disabled':''} onclick="page--;listContent()">‹</button>${Array.from({length:n},(_,i)=>`<button class="${page===i+1?'on':''}" aria-label="${i+1} 페이지" onclick="page=${i+1};listContent()">${i+1}</button>`).join('')}<button aria-label="다음 페이지" ${page===n?'disabled':''} onclick="page++;listContent()">›</button>`:''}</div>`}
function home(){const active=companies.filter(c=>c.visible);shell(`<div class="intro"><div><div class="eyebrow">COMPANY DIRECTORY</div><h1>전북의 가능성을 만나보세요</h1><p>혁신을 만드는 기업, 함께 성장할 투자 파트너.</p></div><div class="numbers"><div>등록기업<b>${active.length}<small style="font-size:14px;font-weight:400"> 개</small></b></div></div></div><div class="search"><svg viewBox="0 0 24 24"><circle cx="10.5" cy="10.5" r="7.5"/><path d="m16 16 5 5"/></svg><input id="search" aria-label="기업명 또는 키워드 검색" placeholder="기업명 또는 관심 있는 키워드를 검색해 보세요" value="${esc(query)}"><button aria-label="검색어 지우기" onclick="query='';$('#search').value='';page=1;listContent()">×</button></div><div id="company-filters">${companyFilterPanel()}</div><div id="results"></div><div class="notice"><div><b>우리 기업의 다음 성장을 준비하고 있나요?</b><p>기업정보와 IR 자료를 등록하고 투자 파트너를 만나보세요.</p></div><a class="btn" href="${user?.role==='company'?'#/mypage':'#/signup'}">기업정보 등록 &nbsp; ↗</a></div>`);$('#search').oninput=e=>{query=e.target.value;page=1;listContent()};listContent()}
function irBytes(c){if(c.irData)return Uint8Array.from(atob(c.irData.split(',')[1]),x=>x.charCodeAt(0));return new TextEncoder().encode(`JB-PORT | 가상 기업 IR 샘플\n\n${c.name}\n${c.summary}\n\n사업소개\n${c.description}\n\n주요 성과\n${c.achievements}\n\n누적 투자유치: ${c.raised}억원\n최근 단계: ${c.stage}\n\n본 자료는 프로토타입 시연을 위한 가상 데이터입니다.`)}function download(bytes,name,type='application/octet-stream'){const url=URL.createObjectURL(new Blob([bytes],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}async function ir(id){const c=companies.find(c=>c.id===id&&(c.visible||user?.role==='admin'||isCompanyOwner(c)));if(!c||!hasPdf(c))return toast('등록된 PDF 자료가 없습니다');try{download(await readPdf(c),pdfName(c),'application/pdf');toast('IR 자료를 다운로드했습니다')}catch(e){toast(e.message)}}
function favorite(id){if(!user){go('/login');toast('관심기업을 저장하려면 로그인해 주세요');return}if(user.role!=='investor'){toast('관심기업 저장은 투자사 회원에게 제공됩니다');return}const f=favorites[user.email]||[];favorites[user.email]=f.includes(id)?f.filter(x=>x!==id):[...f,id];localStorage.setItem('jb-favs',JSON.stringify(favorites));render()}
function detail(id){companyDetail(id)}
function auth(signup){shell(`<div class="auth"><div class="eyebrow">JB-PORT</div><h1>${signup?'회원가입':'로그인'}</h1><p class="muted">${signup?'전북 기업과 함께 새로운 가능성을 시작하세요.':'기업과 투자자를 잇는 연결, JB-PORT.'}</p><form id="authform">${signup?'<div class="rolechoices"><label><input type="radio" name="role" value="company" checked> 기업 회원</label><label><input type="radio" name="role" value="investor"> 투자사 회원</label></div><label class="field">이름 또는 기관명<input name="name" required maxlength="80"></label>':''}<label class="field">이메일<input name="email" type="email" required placeholder="name@company.com"></label><label class="field">비밀번호<input name="password" type="password" minlength="8" required placeholder="8자 이상 입력해 주세요"></label>${signup?'<label class="check"><input type="checkbox" required> 브라우저 내 체험 계정 생성에 동의합니다.</label>':''}<button class="btn primary wide">${signup?'가입하고 시작하기':'로그인'}</button></form><p class="muted" style="text-align:center">${signup?'이미 회원이신가요? <a class="link" href="#/login">로그인</a>':'아직 계정이 없으신가요? <a class="link" href="#/signup">회원가입</a>'}</p><div class="demo"><b>가입 없이 먼저 둘러보세요</b><div><button class="btn" onclick="login('company')">기업 체험</button><button class="btn" onclick="login('investor')">투자사 체험</button><button class="btn" onclick="login('admin')">관리자 체험</button></div></div><p class="smallnote">프론트엔드 체험용 로그인입니다. 계정과 데이터는 이 브라우저에만 저장됩니다. 실제 사용하는 비밀번호는 입력하지 마세요.</p></div>`);$('#authform').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),email=fd.get('email').trim().toLowerCase(),accounts=JSON.parse(localStorage.getItem('jb-accounts')||'{}'),hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(fd.get('password'))))).map(v=>v.toString(16).padStart(2,'0')).join('');if(signup){if(accounts[email])return toast('이미 가입한 이메일입니다');accounts[email]={role:fd.get('role'),hash};localStorage.setItem('jb-accounts',JSON.stringify(accounts));login(fd.get('role'),email)}else{if(!accounts[email]||accounts[email].hash!==hash)return toast('이메일 또는 비밀번호를 확인해 주세요');login(accounts[email].role,email)}}}
function field(label,name,value='',type='text'){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" required ${type==='number'?'min="0" step="0.1"':'maxlength="150"'}></label>`}
function mypage(){if(!user)return auth(false);if(user.role==='admin')return admin();if(user.role==='investor'){const list=companies.filter(c=>c.visible&&(favorites[user.email]||[]).includes(c.id));shell(`<div class="eyebrow">MY PAGE</div><h1>관심기업</h1><p class="muted">다음 성장을 함께하고 싶은 기업을 모았습니다.</p><div class="listbar">저장한 기업 ${list.length}개</div>${list.length?list.map(row).join(''):'<div class="empty">아직 저장한 기업이 없습니다.<br><br><a class="btn primary" href="#/">기업 둘러보기</a></div>'}`);return}const c=companies.find(c=>c.owner===user.email)||(user.email==='company@demo.local'?companies.find(c=>c.id==='1'&&!c.owner)||{}:{});companyPage(c)}
function admin(){if(user?.role!=='admin')return auth(false);shell(`<div class="topline"><div><div class="eyebrow">ADMINISTRATION</div><h1>관리자페이지</h1><p class="muted">등록·수정된 기업정보를 확인한 뒤 공개해 주세요. 검토 전에는 목록에 표시되지 않습니다.</p></div><div class="toolbar"><button class="btn" onclick="exportExcel()">↓ 기업정보 Excel</button><button class="btn primary" onclick="exportIR()">↓ IR 자료 ZIP</button></div></div><div class="listbar">전체 ${companies.length}개 · 공개 ${companies.filter(c=>c.visible).length}개 · 비노출 ${companies.filter(c=>!c.visible).length}개</div><div class="tablewrap"><table><thead><tr><th>기업명</th><th>대표자</th><th>사업 분야</th><th>소재지</th><th>IR 자료</th><th>공개 상태</th></tr></thead><tbody>${companies.map(c=>`<tr><td><a class="admin-company" href="#/company/${c.id}"><span>${esc(c.name)}</span><span aria-hidden="true">↗</span></a></td><td>${esc(c.ceo)}</td><td>${esc(c.sector)}</td><td>${esc(c.city)}</td><td><button class="btn" onclick="ir('${c.id}')" style="padding:6px 10px">다운로드</button></td><td><button class="switch ${c.visible?'on':''}" aria-label="${esc(c.name)} 공개 상태 전환" onclick="toggleVisibility('${c.id}')">${c.visible?'공개 중':c.reviewStatus==='pending'?'검토 대기 · 공개':'비노출 · 공개'}</button></td></tr>`).join('')}</tbody></table></div><p class="smallnote">Excel과 ZIP에는 비노출 기업을 포함한 전체 등록기업이 포함됩니다.</p>`)}function toggleVisibility(id){if(user?.role!=='admin')return;const c=companies.find(c=>c.id===id),next={...c,visible:!c.visible,reviewStatus:c.visible?'hidden':'approved'};const updated=companies.map(x=>x.id===id?next:x);try{localStorage.setItem('jb-companies',JSON.stringify(updated));companies=updated;render();toast(next.visible?'확인 완료: 기업정보를 공개했습니다':'기업정보를 비노출 처리했습니다')}catch{toast('저장 공간 문제로 상태를 변경하지 못했습니다')}}
// Store-mode ZIP supports both uploaded binary documents and Office Open XML files.
function zip(files){const enc=new TextEncoder(),chunks=[],central=[];let offset=0;const u16=(a,o,n)=>new DataView(a.buffer).setUint16(o,n,true),u32=(a,o,n)=>new DataView(a.buffer).setUint32(o,n>>>0,true);for(const [name,data] of files){const n=enc.encode(name),b=typeof data==='string'?enc.encode(data):data;let crc=0xffffffff;for(const v of b){crc^=v;for(let j=0;j<8;j++)crc=(crc>>>1)^((crc&1)?0xedb88320:0)}crc=(crc^0xffffffff)>>>0;const h=new Uint8Array(30+n.length);u32(h,0,0x04034b50);u16(h,4,20);u16(h,6,2048);u32(h,14,crc);u32(h,18,b.length);u32(h,22,b.length);u16(h,26,n.length);h.set(n,30);const d=new Uint8Array(46+n.length);u32(d,0,0x02014b50);u16(d,4,20);u16(d,6,20);u16(d,8,2048);u32(d,16,crc);u32(d,20,b.length);u32(d,24,b.length);u16(d,28,n.length);u32(d,42,offset);d.set(n,46);chunks.push(h,b);central.push(d);offset+=h.length+b.length}const size=central.reduce((n,c)=>n+c.length,0),end=new Uint8Array(22);u32(end,0,0x06054b50);u16(end,8,files.length);u16(end,10,files.length);u32(end,12,size);u32(end,16,offset);const out=new Uint8Array(offset+size+22);let p=0;for(const c of [...chunks,...central,end]){out.set(c,p);p+=c.length}return out}
async function exportIR(){if(user?.role!=='admin')return;const pdfs=companies.filter(hasPdf);if(!pdfs.length)return toast('다운로드할 PDF 자료가 없습니다');try{const files=[];for(const c of pdfs)files.push([c.id+'/'+pdfName(c),await readPdf(c)]);download(zip(files),'JB-PORT_IR_전체.zip','application/zip');toast('등록된 PDF 자료를 다운로드했습니다')}catch(e){toast(e.message)}}
function exportExcel(){if(user?.role!=='admin')return;const rows=exportCompanyRows();const sheet=`<?xml version="1.0" encoding="UTF-8"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>${rows.map((r,i)=>`<row r="${i+1}">${r.map((v,j)=>`<c r="${excelColumn(j)}${i+1}" t="inlineStr"><is><t xml:space="preserve">${esc(v)}</t></is></c>`).join('')}</row>`).join('')}</sheetData></worksheet>`;download(zip([['[Content_Types].xml','<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>'],['_rels/.rels','<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>'],['xl/workbook.xml','<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="등록기업" sheetId="1" r:id="rId1"/></sheets></workbook>'],['xl/_rels/workbook.xml.rels','<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>'],['xl/worksheets/sheet1.xml',sheet]]),'전북기업_등록정보.xlsx','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');toast('기업정보 Excel을 다운로드했습니다')}
function render(){const p=location.hash.slice(1)||'/';if(p.startsWith('/company/'))detail(p.split('/')[2]);else if(p==='/login')auth(false);else if(p==='/signup')auth(true);else if(p==='/mypage')mypage();else if(p==='/admin')admin();else home()}window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});render();

function chooseSort(value){sort=value;page=1;listContent();$('#sort-picker summary')?.focus()}
window.addEventListener('click',e=>{const picker=$('#sort-picker');if(picker&&!picker.contains(e.target))picker.open=false});window.addEventListener('keydown',e=>{const picker=$('#sort-picker');if(e.key==='Escape'&&picker?.open){picker.open=false;picker.querySelector('summary').focus()}});

window.addEventListener('click',e=>{const picker=$('#sector-filter');if(picker&&!picker.contains(e.target))picker.open=false});window.addEventListener('keydown',e=>{if(e.key==='Escape'){const picker=$('#sector-filter');if(picker?.open){picker.open=false;picker.querySelector('summary').focus()}}});

